


export type PaymentMethod = { "card"?: { "brand": "visa" | "mastercard" | "amex" | "discover" | "diners" | "jcb" | "unionpay" | (string & {}); /** Format: int32. */ "exp_month": number; /** Format: int32. */ "exp_year": number; "last4": string; "wallet"?: string; }; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id": string; "email": string; "name"?: string; "phone"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "customer_id": string; "merchant_id"?: string; "payment_method_id": string; /** Where the buyer saved this payment method. Returned on /v1/me/payment-methods responses when Flint wallet support is enabled. Accept future values. */ "saved_with"?: "flint" | "store" | (string & {}); "status": "pending" | "active" | "expired" | "removed" | "failed" | (string & {}); "type": "card" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; /** When Flint may charge the payment method. off_session payment methods can pay subscriptions, automatic invoices, and other charges without the buyer, and can be a customer's default. on_session payment methods were saved by the buyer in checkout for faster checkout at this merchant; Flint charges them only in checkouts the buyer completes and refuses them for any charge without the buyer and as a default. Payment methods saved before usage existed are off_session. */ "usage": "on_session" | "off_session" | (string & {}); };
